import os, torch, hashlib
def safe_load_checkpoint(ckpt_dir):
    files = sorted([f for f in os.listdir(ckpt_dir) if f.startswith('ckpt_') and f.endswith('.pt')], reverse=True)
    for fname in files:
        path = os.path.join(ckpt_dir, fname)
        try:
            if os.path.exists(path + '.sha256'):
                with open(path, 'rb') as f:
                    digest = hashlib.sha256(f.read()).hexdigest()
                with open(path + '.sha256') as f:
                    if f.read().split()[0] != digest:
                        raise ValueError('sha256 mismatch')
            ckpt = torch.load(path, map_location='cpu')
            print(f'Successfully recovered from {fname}')
            return ckpt
        except Exception as e:
            print(f'Skipping corrupted checkpoint {fname}: {e}')
    raise RuntimeError('No valid checkpoint found in directory')
